from pathlib import Path
import hashlib
import re
from openpyxl import load_workbook

TARGET_NAME = "年度限额复核表_BJLYYQ202507230184.xlsx"
CLAIM_NO = "BJLYYQ202507230184"
EXPECTED = {"prior_paid": 1050, "current_approved": 350, "post_paid": 1400, "remaining_limit": 700}
SOURCE_HASHES = {
    "03_规则口径/王芷宁保单给付标准与限额参数表.xlsx": "27737cafe194a28731155bb56e48852500477e0541fc81594f560a4819ab4944",
    "04_核算与复核/MU567航班延误保险金核算主表.xlsx": "039984690954d05c26ea90a1e014f3735ae06821d174aa2770d00d1fed89c691",
}

def _target(ws):
    matches = list(Path(ws).rglob(TARGET_NAME))
    return matches[0] if len(matches) == 1 else None

def _norm(value):
    return re.sub(r"[\s\W_]+", "", str(value or "").casefold())

def _rows(path):
    wb = load_workbook(path, data_only=True, read_only=True)
    try:
        for sheet in wb.worksheets:
            for row in sheet.iter_rows(values_only=True):
                yield list(row)
    finally:
        wb.close()

def _amount_matches(value, amount):
    if isinstance(value, (int, float)):
        return abs(float(value) - amount) <= 0.01
    text = str(value or "")
    for token in re.findall(r"(?<![0-9])(?:\d{1,3}(?:,\d{3})+|\d+(?:\.\d+)?)(?![0-9])", text):
        try:
            if abs(float(token.replace(",", "")) - amount) <= 0.01:
                return True
        except ValueError:
            continue
    return False

def _row_has_label_amount(row, labels, amount):
    normalized = [_norm(value) for value in row]
    normalized_labels = [_norm(label) for label in labels]
    if not any(any(label in cell for label in normalized_labels) for cell in normalized):
        return False
    return any(_amount_matches(value, amount) for value in row)

def _find_amount(path, labels, amount):
    rows = list(_rows(path))
    normalized_labels = [_norm(label) for label in labels]
    for row_index, row in enumerate(rows):
        normalized = [_norm(value) for value in row]
        matching_columns = [index for index, cell in enumerate(normalized)
                            if any(label in cell for label in normalized_labels)]
        if not matching_columns:
            continue
        if _row_has_label_amount(row, labels, amount):
            return True
        for next_row in rows[row_index + 1:row_index + 4]:
            for column in matching_columns:
                if column >= len(next_row):
                    continue
                if _amount_matches(next_row[column], amount):
                    return True
    return False

def check_case_and_prior_paid(ws):
    path = _target(ws)
    if not path:
        return {"score": 0, "detail": f"missing unique {TARGET_NAME}"}
    rows = list(_rows(path))
    has_case = any(CLAIM_NO in " ".join(str(value or "") for value in row) for row in rows)
    has_amount = _find_amount(path, ["事故日前已支付", "事故日前实际已支付", "实际已支付", "既往已支付", "priorpaid"], EXPECTED["prior_paid"])
    return {"score": int(has_case and has_amount), "detail": f"claim_no={has_case}, prior_paid={has_amount}"}

def check_current_approved(ws):
    path = _target(ws)
    ok = bool(path and _find_amount(path, ["本次有效核定", "本次核定", "currentapproved", "approvedamount"], EXPECTED["current_approved"]))
    return {"score": int(ok), "detail": f"current_approved={ok}"}

def check_post_paid(ws):
    path = _target(ws)
    ok = bool(path and _find_amount(path, ["赔付后累计", "赔后累计", "postpaid"], EXPECTED["post_paid"]))
    return {"score": int(ok), "detail": f"post_paid={ok}"}

def check_remaining_limit(ws):
    path = _target(ws)
    ok = bool(path and _find_amount(path, ["剩余限额", "剩余责任限额", "remaininglimit"], EXPECTED["remaining_limit"]))
    return {"score": int(ok), "detail": f"remaining_limit={ok}"}

def check_method_note(ws):
    path = _target(ws)
    if not path:
        return {"score": 0, "detail": "target workbook missing"}
    text = " ".join(str(value or "") for row in _rows(path) for value in row)
    normalized = _norm(text)
    groups = {
        "effective payment": ["事故日前有效支付", "事故日前实际支付", "逐笔", "有效支付", "实际支付"],
        "final result": ["最终有效", "final", "定稿"],
        "snapshot excluded": ["夜间快照", "快照", "不采用"],
        "default excluded": ["产品默认值", "默认值", "不采用"],
        "void excluded": ["作废", "voided", "不采用"],
    }
    found = {name: any(_norm(term) in normalized for term in terms) for name, terms in groups.items()}
    return {"score": int(all(found.values())), "detail": f"method_terms={found}"}

def check_source_files_unchanged(ws):
    root = Path(ws)
    missing, changed = [], []
    for relative, expected_hash in SOURCE_HASHES.items():
        path = root / relative
        if not path.exists():
            missing.append(relative)
        elif hashlib.sha256(path.read_bytes()).hexdigest() != expected_hash:
            changed.append(relative)
    ok = not missing and not changed
    return {"score": int(ok), "detail": "source workbooks unchanged" if ok else f"missing={missing}, changed={changed}"}
